@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #FFFFFF;
  --bg-secondary: #F7F6F3;
  --bg-dark: #0D1117;
  --text: #1A1A2E;
  --text-secondary: #6B7280;
  --text-muted: #9CA3AF;
  --text-inverse: #F9FAFB;
  --accent-green: #55DA9B;
  --accent-green-dark: #3CB87D;
  --accent-coral: #FF6B4A;
  --accent-coral-dark: #E55A3A;
  --accent-purple: #5620C1;
  --border: #E5E7EB;
  --border-dark: #374151;
  --shadow-sm: 0 1px 2px rgba(0,0,0,.05);
  --shadow: 0 4px 6px -1px rgba(0,0,0,.07), 0 2px 4px -1px rgba(0,0,0,.04);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,.08), 0 4px 6px -2px rgba(0,0,0,.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,.1), 0 10px 10px -5px rgba(0,0,0,.04);
  --radius: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --font: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.app { min-height: 100vh; display: flex; flex-direction: column; }
main { flex: 1; }
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { font-family: var(--font); cursor: pointer; border: none; background: none; }

/* ── NAV ─────────────────────────────────────────────────────────────────── */

.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 18px;
  font-weight: 700;
  color: var(--text);
  letter-spacing: -0.3px;
}

.nav-links {
  display: flex;
  gap: 32px;
}

.nav-links a {
  font-size: 15px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color 0.2s;
}

.nav-links a:hover { color: var(--text); }

.nav-auth {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* ── BUTTONS ─────────────────────────────────────────────────────────────── */

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 20px;
  background: var(--accent-green);
  color: var(--bg-dark);
  font-size: 15px;
  font-weight: 600;
  border-radius: var(--radius);
  transition: background 0.2s, transform 0.15s, box-shadow 0.2s;
  white-space: nowrap;
}

.btn-primary:hover {
  background: var(--accent-green-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(85,218,155,0.35);
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  padding: 10px 16px;
  font-size: 15px;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius);
  transition: color 0.2s, background 0.2s;
}

.btn-ghost:hover {
  color: var(--text);
  background: var(--bg-secondary);
}

/* ── HERO ─────────────────────────────────────────────────────────────────── */

.hero {
  position: relative;
  background: var(--bg-dark);
  padding: 80px 24px 64px;
  overflow: hidden;
}

.hero-bg-pattern {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 50% -10%, rgba(86,32,193,0.25) 0%, transparent 60%),
    radial-gradient(ellipse 60% 40% at 80% 110%, rgba(85,218,155,0.15) 0%, transparent 50%),
    radial-gradient(circle at 20% 80%, rgba(255,107,74,0.08) 0%, transparent 40%);
  pointer-events: none;
}

.hero-bg-pattern::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.02'%3E%3Ccircle cx='30' cy='30' r='1.5'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
  opacity: 1;
}

.hero-content {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
  animation: fadeUp 0.7s ease-out;
}

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: rgba(85,218,155,0.12);
  border: 1px solid rgba(85,218,155,0.25);
  border-radius: 100px;
  font-size: 13px;
  font-weight: 600;
  color: var(--accent-green);
  letter-spacing: 0.2px;
}

.badge-dot {
  width: 7px;
  height: 7px;
  background: var(--accent-green);
  border-radius: 50%;
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.6; transform: scale(0.85); }
}

.hero-title {
  font-size: clamp(36px, 6vw, 64px);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -2px;
  color: var(--text-inverse);
}

.hero-subtitle {
  font-size: 20px;
  font-weight: 500;
  color: rgba(249,250,251,0.7);
  margin-top: -8px;
}

.hero-ctas {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  width: 100%;
  max-width: 440px;
  margin-top: 8px;
}

.btn-google {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  padding: 14px 24px;
  background: var(--bg);
  color: var(--text);
  font-size: 16px;
  font-weight: 600;
  border-radius: var(--radius);
  transition: background 0.2s, transform 0.15s, box-shadow 0.2s;
  box-shadow: var(--shadow-lg);
}

.btn-google:hover {
  background: var(--bg-secondary);
  transform: translateY(-1px);
  box-shadow: var(--shadow-xl);
}

.hero-email-form {
  display: flex;
  gap: 8px;
  width: 100%;
}

.input-email {
  flex: 1;
  padding: 14px 16px;
  font-size: 15px;
  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  border: 2px solid transparent;
  border-radius: var(--radius);
  outline: none;
  transition: border-color 0.2s;
}

.input-email:focus {
  border-color: var(--accent-green);
}

.input-email::placeholder { color: var(--text-muted); }

.btn-email {
  padding: 14px 20px;
  background: var(--accent-coral);
  color: white;
  font-size: 15px;
  font-weight: 600;
  border-radius: var(--radius);
  white-space: nowrap;
  transition: background 0.2s, transform 0.15s;
}

.btn-email:hover {
  background: var(--accent-coral-dark);
  transform: translateY(-1px);
}

.hero-legal {
  font-size: 12px;
  color: rgba(249,250,251,0.45);
  max-width: 400px;
  line-height: 1.5;
}

.hero-legal a { color: rgba(249,250,251,0.6); text-decoration: underline; }
.hero-legal a:hover { color: var(--text-inverse); }

.category-pills {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-top: 12px;
  max-width: 700px;
}

.pill {
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 500;
  color: rgba(249,250,251,0.7);
  background: rgba(255,255,255,0.07);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 100px;
  transition: all 0.2s;
}

.pill:hover, .pill-active {
  background: rgba(85,218,155,0.15);
  border-color: rgba(85,218,155,0.35);
  color: var(--accent-green);
}

/* ── SECTIONS ─────────────────────────────────────────────────────────────── */

.section-title {
  font-size: clamp(28px, 4vw, 40px);
  font-weight: 800;
  letter-spacing: -1.5px;
  color: var(--text);
  text-align: center;
  margin-bottom: 48px;
}

.section-subtitle {
  font-size: 17px;
  color: var(--text-secondary);
  max-width: 600px;
  margin-top: 8px;
  line-height: 1.6;
}

/* ── FEATURES ─────────────────────────────────────────────────────────────── */

.features {
  padding: 80px 24px;
  background: var(--bg);
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 24px;
  max-width: 1000px;
  margin: 0 auto;
}

.feature-card {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 24px;
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  transition: transform 0.2s, box-shadow 0.2s;
}

.feature-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.feature-icon {
  font-size: 28px;
  flex-shrink: 0;
  line-height: 1;
}

.feature-text {
  font-size: 15px;
  line-height: 1.5;
  color: var(--text-secondary);
}

.feature-text strong { color: var(--text); }

/* ── STATS ─────────────────────────────────────────────────────────────────── */

.stats {
  padding: 60px 24px;
  background: var(--bg-dark);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  text-align: center;
}

.stat-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-value {
  font-size: clamp(40px, 6vw, 64px);
  font-weight: 800;
  letter-spacing: -3px;
  color: var(--text-inverse);
  line-height: 1;
}

.stat-label {
  font-size: 15px;
  font-weight: 500;
  color: rgba(249,250,251,0.55);
}

/* ── COURSES ─────────────────────────────────────────────────────────────── */

.courses {
  padding: 80px 24px;
  background: var(--bg-secondary);
}

.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 40px;
  justify-content: center;
}

.tab {
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  background: transparent;
  border: 1.5px solid var(--border);
  border-radius: 100px;
  transition: all 0.2s;
}

.tab:hover {
  border-color: var(--text-secondary);
  color: var(--text);
}

.tab-active {
  background: var(--bg-dark);
  border-color: var(--bg-dark);
  color: var(--text-inverse);
}

.courses-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
  max-width: 1200px;
  margin: 0 auto;
}

.course-card {
  background: var(--bg);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border);
  transition: transform 0.2s, box-shadow 0.2s;
  cursor: pointer;
}

.course-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.course-thumb {
  position: relative;
  aspect-ratio: 16/10;
  overflow: hidden;
  background: var(--bg-secondary);
}

.course-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s;
}

.course-card:hover .course-thumb img {
  transform: scale(1.04);
}

.course-duration {
  position: absolute;
  bottom: 10px;
  right: 10px;
  padding: 4px 10px;
  background: rgba(13,17,23,0.85);
  backdrop-filter: blur(4px);
  color: var(--text-inverse);
  font-size: 12px;
  font-weight: 600;
  border-radius: 6px;
}

.course-info {
  padding: 16px;
}

.course-title {
  font-size: 15px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--text);
  margin-bottom: 6px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.course-instructor {
  font-size: 13px;
  color: var(--text-secondary);
  margin-bottom: 10px;
}

.course-meta {
  display: flex;
  align-items: center;
  gap: 12px;
}

.students {
  font-size: 12px;
  color: var(--text-muted);
}

/* ── CREATIVE FEED ─────────────────────────────────────────────────────────── */

.creative-feed {
  padding: 80px 24px;
  background: var(--bg);
}

.feed-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  max-width: 1000px;
  margin: 0 auto;
}

.feed-card {
  padding: 32px 28px;
  background: var(--bg-secondary);
  border-radius: var(--radius-xl);
  border: 1px solid var(--border);
  text-align: center;
  transition: transform 0.2s, box-shadow 0.2s;
}

.feed-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.feed-icon {
  font-size: 40px;
  margin-bottom: 16px;
}

.feed-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 8px;
}

.feed-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ── TEACHERS ─────────────────────────────────────────────────────────────── */

.teachers {
  padding: 80px 24px;
  background: var(--bg-secondary);
  overflow: hidden;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  max-width: 1200px;
  margin: 0 auto 40px;
  gap: 24px;
}

.carousel-controls {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  border: 1.5px solid var(--border);
  border-radius: 50%;
  color: var(--text);
  transition: all 0.2s;
}

.carousel-btn:hover:not(.disabled) {
  background: var(--bg-dark);
  border-color: var(--bg-dark);
  color: var(--text-inverse);
}

.carousel-btn.disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.teachers-scroll {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  padding: 8px 4px 16px;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  max-width: 1200px;
  margin: 0 auto;
}

.teachers-scroll::-webkit-scrollbar { display: none; }

.teacher-card {
  flex-shrink: 0;
  width: 180px;
  scroll-snap-align: start;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 24px 16px;
  background: var(--bg);
  border-radius: var(--radius-xl);
  border: 1px solid var(--border);
  transition: transform 0.2s, box-shadow 0.2s;
  cursor: default;
}

.teacher-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.teacher-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  overflow: hidden;
  border: 3px solid var(--accent-green);
  flex-shrink: 0;
}

.teacher-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.teacher-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--text);
  text-align: center;
}

.teacher-specialty {
  font-size: 12px;
  color: var(--text-secondary);
  text-align: center;
  line-height: 1.4;
}

/* ── TESTIMONIALS ─────────────────────────────────────────────────────────── */

.testimonials {
  padding: 80px 24px;
  background: var(--bg);
}

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 1000px;
  margin: 0 auto;
}

.testimonial-card {
  padding: 32px;
  background: var(--bg-secondary);
  border-radius: var(--radius-xl);
  border: 1px solid var(--border);
  position: relative;
  transition: transform 0.2s, box-shadow 0.2s;
}

.testimonial-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.quote-mark {
  font-size: 72px;
  font-weight: 800;
  color: var(--accent-green);
  line-height: 0.8;
  margin-bottom: 8px;
  font-family: Georgia, serif;
  opacity: 0.5;
}

.testimonial-quote {
  font-size: 16px;
  line-height: 1.7;
  color: var(--text);
  margin-bottom: 20px;
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.author-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  object-fit: cover;
}

.author-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
}

/* ── TEAMS ─────────────────────────────────────────────────────────────────── */

.teams {
  padding: 80px 24px;
  background: var(--bg-secondary);
}

.teams-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  max-width: 1100px;
  margin: 0 auto;
  background: var(--bg-dark);
  border-radius: var(--radius-xl);
  padding: 56px 64px;
  overflow: hidden;
  position: relative;
}

.teams-title {
  font-size: clamp(28px, 3.5vw, 40px);
  font-weight: 800;
  letter-spacing: -1.5px;
  color: var(--text-inverse);
  margin-bottom: 16px;
}

.teams-desc {
  font-size: 16px;
  line-height: 1.7;
  color: rgba(249,250,251,0.65);
  margin-bottom: 28px;
}

.btn-teams {
  display: inline-flex;
  align-items: center;
  padding: 12px 28px;
  background: var(--accent-coral);
  color: white;
  font-size: 15px;
  font-weight: 600;
  border-radius: var(--radius);
  transition: background 0.2s, transform 0.15s;
}

.btn-teams:hover {
  background: var(--accent-coral-dark);
  transform: translateY(-1px);
}

.teams-visual {
  display: flex;
  align-items: center;
  justify-content: center;
}

.teams-shapes {
  position: relative;
  width: 280px;
  height: 200px;
}

.shape {
  position: absolute;
  border-radius: 50%;
  opacity: 0.7;
}

.shape-1 {
  width: 140px;
  height: 140px;
  background: var(--accent-green);
  top: 20px;
  left: 20px;
  animation: float 6s ease-in-out infinite;
}

.shape-2 {
  width: 100px;
  height: 100px;
  background: var(--accent-purple);
  top: 0;
  right: 20px;
  animation: float 5s ease-in-out infinite reverse;
}

.shape-3 {
  width: 80px;
  height: 80px;
  background: var(--accent-coral);
  bottom: 10px;
  right: 60px;
  animation: float 7s ease-in-out infinite 1s;
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-15px); }
}

/* ── FAQ ─────────────────────────────────────────────────────────────────── */

.faq {
  padding: 80px 24px;
  background: var(--bg);
}

.faq-list {
  max-width: 760px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  overflow: hidden;
}

.faq-item {
  border-bottom: 1px solid var(--border);
  transition: background 0.2s;
}

.faq-item:last-child { border-bottom: none; }

.faq-item:hover { background: var(--bg-secondary); }

.faq-open { background: var(--bg-secondary); }

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 28px;
  font-size: 16px;
  font-weight: 600;
  color: var(--text);
  text-align: left;
  transition: color 0.2s;
}

.faq-question:hover { color: var(--accent-coral); }

.faq-icon {
  flex-shrink: 0;
  color: var(--text-muted);
  transition: transform 0.3s;
}

.faq-open .faq-icon { transform: rotate(180deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.faq-open .faq-answer { max-height: 200px; }

.faq-answer p {
  padding: 0 28px 20px;
  font-size: 15px;
  line-height: 1.7;
  color: var(--text-secondary);
}

/* ── FOOTER ─────────────────────────────────────────────────────────────── */

.footer {
  background: var(--bg-dark);
  padding: 64px 24px 32px;
}

.footer-top {
  max-width: 1200px;
  margin: 0 auto 48px;
  display: grid;
  grid-template-columns: 240px 1fr;
  gap: 64px;
}

.footer-brand .nav-logo { color: var(--text-inverse); }

.footer-links-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
}

.footer-link-group h4 {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-inverse);
  text-transform: uppercase;
  letter-spacing: 0.8px;
  margin-bottom: 14px;
}

.footer-link-group ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.footer-link-group a {
  font-size: 13px;
  color: rgba(249,250,251,0.5);
  transition: color 0.2s;
}

.footer-link-group a:hover { color: var(--text-inverse); }

.footer-bottom {
  max-width: 1200px;
  margin: 0 auto;
  padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,0.08);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.footer-legal {
  font-size: 12px;
  color: rgba(249,250,251,0.35);
  line-height: 1.6;
}

.footer-copy {
  font-size: 13px;
  color: rgba(249,250,251,0.4);
}

/* ── RESPONSIVE ─────────────────────────────────────────────────────────────── */

@media (max-width: 1024px) {
  .nav-links { display: none; }
  .footer-top { grid-template-columns: 1fr; gap: 40px; }
  .footer-links-grid { grid-template-columns: repeat(3, 1fr); }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .teams-card { grid-template-columns: 1fr; padding: 40px 32px; }
  .teams-visual { display: none; }
  .section-header { flex-direction: column; align-items: flex-start; }
}

@media (max-width: 768px) {
  .hero { padding: 56px 20px 48px; }
  .hero-title { letter-spacing: -1px; }
  .hero-email-form { flex-direction: column; }
  .category-pills { justify-content: center; }
  .features, .courses, .creative-feed, .teachers, .testimonials, .teams, .faq { padding: 56px 20px; }
  .section-title { margin-bottom: 32px; }
  .features-grid { grid-template-columns: 1fr 1fr; }
  .courses-grid { grid-template-columns: 1fr; }
  .feed-grid { grid-template-columns: 1fr; }
  .testimonials-grid { grid-template-columns: 1fr; }
  .footer-links-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }
  .stat-value { font-size: 40px; letter-spacing: -1.5px; }
  .faq-question { padding: 16px 20px; font-size: 15px; }
  .faq-answer p { padding: 0 20px 16px; }
}

@media (max-width: 480px) {
  .features-grid { grid-template-columns: 1fr; }
  .footer-links-grid { grid-template-columns: 1fr 1fr; }
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .nav-auth .btn-ghost { display: none; }
}

/* ── SCROLLBAR ─────────────────────────────────────────────────────────────── */

::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

