cd /app && node -e "
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on('console', msg => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  page.on('pageerror', err => errors.push(err.message));

  await page.goto('file:///app/output/index.html', { waitUntil: 'networkidle', timeout: 15000 });
  await page.waitForTimeout(2000);

  const title = await page.title();
  const heroTitle = await page.textContent('.hero-title').catch(() => 'NOT FOUND');
  const navExists = await page.locator('.nav').count();
  const footerExists = await page.locator('.footer').count();

  console.log('Title:', title);
  console.log('Hero title:', heroTitle);
  console.log('Nav exists:', navExists > 0);
  console.log('Footer exists:', footerExists > 0);
  console.log('Console errors:', errors.length > 0 ? errors.join('; ') : 'None');

  await browser.close();
})().catch(e => { console.error('ERROR:', e.message); process.exit(1); });
" 2>&1

